const { DatabaseSync } = require('node:sqlite');
const path = require('path');

const db = new DatabaseSync(path.join(process.env.USERPROFILE, '.cc-switch/cc-switch.db'));
const rows = db.prepare('SELECT id, name, app_type, is_current, settings_config FROM providers ORDER BY app_type, name').all();

function redact(obj) {
  if (!obj || typeof obj !== 'object') return obj;
  const out = Array.isArray(obj) ? [...obj] : { ...obj };
  for (const [k, v] of Object.entries(out)) {
    if (/key|token|secret|password/i.test(k) && typeof v === 'string' && v.length > 8) {
      out[k] = v.slice(0, 10) + '...' + v.slice(-4);
    } else if (typeof v === 'object') out[k] = redact(v);
    else if (typeof v === 'string' && v.includes('sk-')) {
      out[k] = v.replace(/sk-[A-Za-z0-9]+/g, (m) => m.slice(0, 10) + '...' + m.slice(-4));
    }
  }
  return out;
}

for (const r of rows) {
  const cfg = JSON.parse(r.settings_config || '{}');
  console.log('\n===', r.app_type, r.name, r.id, 'current=' + r.is_current, '===');
  console.log(JSON.stringify(redact(cfg), null, 2));
}

