async function test(url) {
  const body = {
    model: 'gpt-5.5',
    input: 'Reply with exactly: OK',
    stream: false,
    max_output_tokens: 16,
  };
  const started = Date.now();
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${key}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(30000),
    });
    const text = await res.text();
    let msg = text.slice(0, 200);
    try {
      const j = JSON.parse(text);
      msg = j.error?.message || j.status || msg;
    } catch {}
    console.log(`${url}\n  HTTP ${res.status} ${Date.now() - started}ms\n  ${msg}\n`);
    return res.status;
  } catch (e) {
    console.log(`${url}\n  FAIL ${Date.now() - started}ms\n  ${e.message}\n`);
    return 0;
  }
}

(async () => {
  for (const url of endpoints) await test(url);
})();

const { DatabaseSync } = require('node:sqlite');
const fs = require('fs');
const path = require('path');

const home = process.env.USERPROFILE;
const dbPath = path.join(home, '.cc-switch/cc-switch.db');
const configPath = path.join(home, '.codex/config.toml');
const settingsPath = path.join(home, '.cc-switch/settings.json');
const providerId = 'hcai-1780897183339';
const upstream = 'https://ai.hctopup.com/v1';

const providerConfig = `model_provider = "custom"
model = "gpt-5.5"
model_reasoning_effort = "high"
disable_response_storage = true

[model_providers.custom]
name = "HCAI"
base_url = "${upstream}"
wire_api = "responses"
requires_openai_auth = true
`;

// 1) Update CC Switch provider template (direct upstream, no local proxy)
const db = new DatabaseSync(dbPath);
const row = db.prepare('SELECT settings_config FROM providers WHERE id = ?').get(providerId);
if (!row) {
  console.error('Provider not found:', providerId);
  process.exit(1);
}
const cfg = JSON.parse(row.settings_config || '{}');
cfg.config = providerConfig;
db.prepare('UPDATE providers SET settings_config = ? WHERE id = ?').run(JSON.stringify(cfg), providerId);

// 2) Disable proxy takeover flags for codex if table exists
try {
  const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all().map((r) => r.name);
  if (tables.includes('proxy_app_state')) {
    db.prepare("UPDATE proxy_app_state SET is_taken_over = 0 WHERE app = 'codex'").run();
  }
} catch {}

// 3) Patch live config.toml base_url only (preserve MCP/plugins blocks)
let toml = fs.readFileSync(configPath, 'utf8');
toml = toml.replace(/base_url\s*=\s*"[^"]+"/, `base_url = "${upstream}"`);
toml = toml.replace(/\nexperimental_bearer_token\s*=\s*"PROXY_MANAGED"\n/, '\n');
if (!toml.includes(`base_url = "${upstream}"`)) {
  throw new Error('Failed to patch config.toml base_url');
}
fs.writeFileSync(configPath, toml, 'utf8');

// 4) CC Switch settings: stop auto local proxy takeover
const settings = JSON.parse(fs.readFileSync(settingsPath, 'utf8'));
settings.enableLocalProxy = false;
fs.writeFileSync(settingsPath, JSON.stringify(settings, null, 2) + '\n', 'utf8');

console.log('OK');
console.log('- provider template ->', upstream);
console.log('- config.toml base_url ->', upstream);
console.log('- removed PROXY_MANAGED token');
console.log('- enableLocalProxy -> false');

